<?php

use App\Modules\Lead\Http\Controllers\ImportLeadsController;
use App\Modules\Lead\Http\Controllers\LeadController;
use App\Modules\Lead\Http\Controllers\StoreLeadController;
use Illuminate\Support\Facades\Route;

// Public capture endpoint for visit/sell/rent/contact requests from the
// showcase site - rate-limited more strictly than reads (PROJECT_RULES.md
// §22).
Route::middleware('throttle:leads')->post('/leads', StoreLeadController::class);

// Admin sees every lead; a Commercial/SeniorCommercial sees only leads
// generated by their own properties (LeadFilter/LeadPolicy). destroy()
// stays Admin-only - deleting leads isn't a Commercial capability.
Route::middleware(['auth:sanctum', 'role:Admin|Commercial|SeniorCommercial'])->group(function () {
    Route::post('/leads/import', ImportLeadsController::class);
    Route::get('/leads/assignment-options', [LeadController::class, 'assignmentOptions'])->middleware('role:Admin');
    Route::post('/leads/assign', [LeadController::class, 'assign'])->middleware('role:Admin');
    Route::get('/leads', [LeadController::class, 'index']);
    Route::get('/leads/{lead}', [LeadController::class, 'show']);
    Route::patch('/leads/{lead}', [LeadController::class, 'updateStatus']);
    Route::patch('/leads/{lead}/contact', [LeadController::class, 'updateContact']);
});

Route::middleware(['auth:sanctum', 'role:Admin'])->group(function () {
    Route::delete('/leads/{lead}', [LeadController::class, 'destroy']);
});
